export async function main(ns) {
  const targets = ['n00dles','foodnstuff','sigma-cosmetics','joesguns','nectar-net','hong-fu-tea','harakiri-sushi'];

  // Try to gain root on all targets
  for (const t of targets) {
    try { ns.brutessh(t); } catch(e) {}
    try { ns.ftpcrack(t); } catch(e) {}
    try { ns.relaysmtp(t); } catch(e) {}
    try { ns.httpworm(t); } catch(e) {}
    try { ns.sqlinject(t); } catch(e) {}
    try { ns.nuke(t); } catch(e) {}
  }

  let tick = 0;
  while(true) {
    // Find best target
    let best = null, bestMoney = 0;
    for (const t of targets) {
      if (!ns.hasRootAccess(t)) continue;
      const req = ns.getServerRequiredHackingLevel(t);
      if (ns.getHackingLevel() < req) continue;
      const maxMon = ns.getServerMaxMoney(t);
      if (maxMon > bestMoney) { best = t; bestMoney = maxMon; }
    }

    if (!best) {
      await ns.asleep(1000);
      continue;
    }

    // Execute action
    const minSec = ns.getServerMinSecurityLevel(best);
    const curSec = ns.getServerSecurityLevel(best);
    const curMon = ns.getServerMoneyAvailable(best);
    const maxMon = ns.getServerMaxMoney(best);

    if (curSec > minSec + 5) {
      await ns.weaken(best);
    } else if (curMon < maxMon * 0.75) {
      await ns.grow(best);
    } else {
      await ns.hack(best);
    }

    tick++;
    if (tick % 50 === 0) {
      ns.print(`Target: ${best}, Money: ${ns.formatNumber(curMon)}`);
    }
  }
}

